// @ts-check
import { defineConfig } from "astro/config";

// Static output only. The marketing surface is prerendered at build time and
// served either as Cloudflare assets (Candidate A) or through the combined
// edge Worker's `ASSETS` binding (Candidate B). There is no adapter, no
// on-demand rendering, and no runtime content fetch.
//
// The sitemap is authored in `public/sitemap.xml` rather than generated by
// `@astrojs/sitemap`: the site has two physical routes, and adding an
// integration would edit the frozen package manifest and the shared lockfile,
// which this phase must not touch. `tests/site/static-output.test.ts` asserts
// the authored sitemap still matches the built route set.
export default defineConfig({
  site: "https://ariadnev.com",
  output: "static",
  trailingSlash: "never",
  build: {
    format: "file",
    // The stylesheet is small and there are two pages, so a separate request
    // buys almost no cache reuse while costing a round trip on the critical
    // path. Inlining it removes that hop; the content security policy allows
    // the inlined block by hash, and tests/site recomputes the hash from the
    // build so a stale allowance cannot ship.
    inlineStylesheets: "always",
  },
  compressHTML: true,
  devToolbar: { enabled: false },
  vite: {
    build: {
      // One graph enhancer is the entire client budget; never split it into
      // additional chunks that would ship as extra requests.
      assetsInlineLimit: 0,
    },
  },
});
